function csv(text) {
  const rows=[];let row=[],cell='',quoted=false,closed=false,line=1,column=1,quoteLine=0,quoteColumn=0;
  const fail=(message)=>{const error=new Error(message);error.line=quoteLine||line;error.column=quoteColumn||column;throw error;};
  const field=()=>{row.push(cell);cell='';closed=false;};
  const record=()=>{field();if(!(row.length===1&&row[0]===''))rows.push(row);row=[];};
  for(let i=0;i<text.length;i++){
    const ch=text[i];
    if(quoted){
      if(ch==='"'&&text[i+1]==='"'){cell+='"';i++;column++;}
      else if(ch==='"'){quoted=false;closed=true;}
      else cell+=ch;
    }else if(ch==='"'){
      if(cell||closed)fail('Unexpected quote');quoted=true;quoteLine=line;quoteColumn=column;
    }else if(ch===',')field();
    else if(ch==='\n'||ch==='\r'){
      record();if(ch==='\r'&&text[i+1]==='\n')i++;
    }else {if(closed)fail('Characters after closing quote');cell+=ch;}
    if(ch==='\r'){line++;column=1;}else if(ch==='\n'){if(text[i-1]!=='\r')line++;column=1;}else column++;
  }
  if(quoted)fail('Unterminated quoted field');if(cell||row.length||closed)record();return rows;
}
function table(text,header){
  const rows=csv(text);if(JSON.stringify(rows.shift())!==JSON.stringify(header))throw Error('Invalid CSV header');
  return rows.map(row=>{if(row.length!==header.length)throw Error('Invalid CSV column count');return Object.fromEntries(header.map((key,i)=>[key,row[i]]));});
}
function cents(value){
  if(!/^\d+(?:\.\d{1,2})?$/.test(value))throw Error('Amount requires nonnegative decimal cents');
  const [whole,fraction='']=value.split('.');const result=Number(whole)*100+Number(fraction.padEnd(2,'0'));
  if(!Number.isSafeInteger(result))throw Error('Amount exceeds exact integer range');return result;
}
function unique(rows,subject){const seen=new Set();for(const row of rows){if(!row.id||seen.has(row.id))throw Error(`Invalid/duplicate ${subject} id`);seen.add(row.id);}return seen;}
function build({customers,invoices,credits}){
  const customerRows=table(customers,['id','name']);const ids=unique(customerRows,'customer');
  if(customerRows.some(r=>!r.name))throw Error('Customer name required');
  const invoiceRows=table(invoices,['id','customer_id','amount','currency']).map(r=>{
    if(!ids.has(r.customer_id))throw Error('Unknown customer');if(!/^[A-Z]{3}$/.test(r.currency))throw Error('Invalid currency');
    return{id:r.id,customerId:r.customer_id,cents:cents(r.amount),currency:r.currency};
  });unique(invoiceRows,'invoice');const invoicesById=new Map(invoiceRows.map(r=>[r.id,r]));
  const creditRows=credits===undefined?[]:table(credits,['id','invoice_id','amount']).map(r=>{
    if(!invoicesById.has(r.invoice_id))throw Error('Unknown invoice');return{id:r.id,invoiceId:r.invoice_id,cents:cents(r.amount)};
  });unique(creditRows,'credit');const credited=new Map();
  for(const row of creditRows){const total=(credited.get(row.invoiceId)||0)+row.cents;if(!Number.isSafeInteger(total)||total>invoicesById.get(row.invoiceId).cents)throw Error('Over-credit');credited.set(row.invoiceId,total);}
